for t in new:
    if t["id"] == "img-a-pepsin":
        t["q"] = "А қисығы қай ферменттің белсенділігін көрсетеді? Дұрыс ферментті ұяшыққа қой"
        t["options"] += ["Трипсин", "Сілекей амилазасы", "Липаза", "Мальтаза"]
        from PIL import ImageFont
        im = Image.open(f"{repo}/{t['img'][0]}").convert("RGB")
        ImageDraw.Draw(im).text((735, 135), "А қисығы —", fill=(40, 40, 40), font=ImageFont.truetype("/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf", 30))
        im.save(f"{repo}/{t['img'][0]}", quality=88)
# js/images.js: ескі тапсырмалар (папкасымен) + жаңалары, папка ретімен
txt = open(f"{repo}/js/images.js", encoding="utf-8").read()
start = txt.index("window.IMAGE_TASKS = ["); end = txt.rindex("];")
old = [json.loads(l.rstrip().rstrip(",")) for l in txt[start:end].split("\n")[1:] if l.strip().startswith("{")]
old = [t for t in old if not t["id"].startswith("img-a-")]
for t in old: t["folder"] = OLD[t["id"]]
allt = old + new
order = {f[0]: i for i, f in enumerate(FOLDERS)}
oldi = {k: i for i, k in enumerate(OLD)}
allt.sort(key=lambda t: (order[t["folder"]], oldi.get(t["id"], 1000)))
head = "".join(l for l in txt[:start].splitlines(True) if not l.startswith("window.IMAGE_FOLDERS"))
out = head + "window.IMAGE_FOLDERS = " + json.dumps([{"id": a, "module": m, "title": t} for a, m, t in FOLDERS], ensure_ascii=False) + ";\n" \
    + "window.IMAGE_TASKS = [\n" + "\n".join(json.dumps(t, ensure_ascii=False) + "," for t in allt) + "\n];\n"
open(f"{repo}/js/images.js", "w", encoding="utf-8").write(out)
print(len(allt), "tasks;", len(new), "new")
